'use strict';

/*
 * Builds the Bootstrap copy the eForm chrome uses (issue #3944).
 *
 * The eForm renderers (efmshowform_data.jsp, efmformadd_data.jsp) used to add the vendored
 * bootstrap.min.css to every eForm, and its reboot restyled the legacy form underneath. They now add
 * the file this script writes instead: the same stylesheet with every rule confined to elements
 * inside .carlos-eform-ui (see scripts/lib/css-scope.js). The floating toolbar wrapper, the save
 * alert host and the attachment picker carry that class; eForm content never does.
 *
 * The output is committed so the WAR build needs no Node step. scripts/eform-bootstrap-scope.test.js
 * fails when it no longer matches what this script produces from the vendored source, so a Bootstrap
 * upgrade (change SOURCE) or a transform change cannot ship a stale copy.
 *
 *   node scripts/build-eform-scoped-bootstrap.js          write the scoped stylesheet
 *   node scripts/build-eform-scoped-bootstrap.js --check  exit 1 if the committed copy is stale
 */

const fs = require('node:fs');
const path = require('node:path');
const { scopeStylesheet } = require('./lib/css-scope');

const SCOPE_CLASS = 'carlos-eform-ui';
const SOURCE = 'src/main/webapp/library/bootstrap/5.3.8/css/bootstrap.min.css';
const OUTPUT = 'src/main/webapp/eform/eformFloatingToolbar/bootstrap-eform-scoped.min.css';
const ROOT = path.join(__dirname, '..');
const CHARSET = '@charset "UTF-8";';

const NOTICE = `/* Generated by scripts/build-eform-scoped-bootstrap.js from ${SOURCE.replace('src/main/webapp/', '')};`
  + ` do not edit. Every rule applies only inside .${SCOPE_CLASS}, the CARLOS eForm chrome`
  + ' (toolbar, save alert, attachment picker), so the eForm itself keeps its own styling'
  + ' (issue #3944). Bootstrap\'s MIT notice follows. */';

/**
 * The scoped stylesheet for a Bootstrap build.
 *
 * @param {string} sourceCss the vendored bootstrap.min.css
 * @returns {string} the committed file's exact contents
 */
function build(sourceCss) {
  // @charset is honoured only as the very first bytes of a stylesheet, and Bootstrap needs it (it
  // has literal non-ASCII content strings), so the generated-file notice goes after it.
  let body = sourceCss.replace(/^﻿/, '');
  if (body.startsWith(CHARSET)) body = body.slice(CHARSET.length);
  const scoped = scopeStylesheet(body, SCOPE_CLASS).replace(/\/\*# sourceMappingURL=[^*]*\*\/\s*$/, '');
  return `${CHARSET}${NOTICE}\n${scoped.trimEnd()}\n`;
}

function main(argv) {
  const expected = build(fs.readFileSync(path.join(ROOT, SOURCE), 'utf8'));
  const target = path.join(ROOT, OUTPUT);
  if (argv.includes('--check')) {
    const current = fs.existsSync(target) ? fs.readFileSync(target, 'utf8') : '';
    if (current !== expected) {
      console.error(`${OUTPUT} is stale; run: node scripts/build-eform-scoped-bootstrap.js`);
      return 1;
    }
    console.log(`${OUTPUT} is up to date`);
    return 0;
  }
  fs.writeFileSync(target, expected);
  console.log(`wrote ${OUTPUT} (${expected.length} bytes)`);
  return 0;
}

if (require.main === module) {
  process.exit(main(process.argv.slice(2)));
}

module.exports = { SCOPE_CLASS, SOURCE, OUTPUT, build, main };
